```ts
import { Component, inject } from '@angular/core'
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms'
import { NAVIGATE } from '../app/tokens'

const OPTIONS: ReadonlyArray<{ value: string; label: string; target: string }> = [
  { value: '1', label: 'Pagar una orden', target: 'SCR-PAGOORD' },
  // The spec does not state which screen "Consultar una orden" opens.
  // SCR-PAGORES is assumed (as in the prototype); confirm at gate C2.
  { value: '2', label: 'Consultar una orden', target: 'SCR-PAGORES' },
]

function today(): string {
  const d = new Date()
  const two = (n: number): string => String(n).padStart(2, '0')
  return `${two(d.getDate())}/${two(d.getMonth() + 1)}/${two(d.getFullYear() % 100)}`
}

@Component({
  selector: 'app-pagomen',
  standalone: true,
  imports: [ReactiveFormsModule],
  template: `
    <main class="nx-root nx-screen" aria-label="BANCO FICTICIO - PAGOS">
      <header class="nx-screen__header">
        <h1 class="nx-screen__title">BANCO FICTICIO - PAGOS</h1>
      </header>

      <form class="nx-screen__body" [formGroup]="form" (ngSubmit)="submit()" novalidate>
        <div class="nx-field" data-field="FECHA">
          <span class="nx-field__label">FECHA</span>
          <p>{{ fecha }}</p>
        </div>

        <section class="nx-card">
          <ul aria-label="Opciones disponibles">
            @for (o of options; track o.value) {
              <li>{{ o.value }}. {{ o.label }}</li>
            }
          </ul>

          <div class="nx-field" data-field="OPCION">
            <label class="nx-field__label" for="opcion">OPCION</label>
            <input
              id="opcion"
              class="nx-input"
              type="text"
              formControlName="OPCION"
              maxlength="1"
              inputmode="numeric"
              required
              (input)="onInput($event)"
            />
            @if (error) {
              <p class="nx-field__error" role="alert">{{ error }}</p>
            }
          </div>
        </section>

        <div class="nx-field" data-field="MENSAJE">
          <span class="nx-field__label">MENSAJE</span>
          @if (mensajeError) {
            <p class="nx-alert nx-alert--error">{{ mensaje }}</p>
          } @else {
            <p>{{ mensaje }}</p>
          }
        </div>

        <div class="nx-card">
          <button type="submit" class="nx-button nx-button--primary" data-action="ENTER">CONTINUAR</button>
          <button type="button" class="nx-button nx-button--secondary" data-action="PF3" (click)="salir()">SALIR</button>
        </div>
      </form>
    </main>
  `,
})
export class PagomenScreen {
  private readonly navigate = inject(NAVIGATE)

  readonly options = OPTIONS
  readonly fecha = today()

  readonly form = new FormGroup({
    OPCION: new FormControl<string>('', { nonNullable: true, validators: [Validators.required] }),
  })

  error = ''
  mensaje = ''
  mensajeError = false

  onInput(event: Event): void {
    const el = event.target as HTMLInputElement
    const digit = el.value.replace(/\D/g, '').slice(0, 1)
    if (el.value !== digit) {
      el.value = digit
    }
    this.form.controls.OPCION.setValue(digit)
    if (this.error) {
      this.error = ''
    }
  }

  submit(): void {
    const opcion = this.form.controls.OPCION.value.trim()
    if (opcion === '') {
      this.fail('Ingrese una opción (campo obligatorio).')
      return
    }
    const found = OPTIONS.find((o) => o.value === opcion)
    if (!found) {
      this.fail('Opción inválida. Ingrese 1 o 2.')
      return
    }
    this.error = ''
    this.mensajeError = false
    this.mensaje = `Opción ${found.value} seleccionada: ${found.label}.`
    this.navigate(found.target)
  }

  salir(): void {
    this.error = ''
    this.mensajeError = false
    this.mensaje = 'Ha salido del menú de pagos.'
  }

  private fail(msg: string): void {
    this.error = msg
    this.mensaje = msg
    this.mensajeError = true
  }
}
